<template><app-layout><h1 class="text-2xl font-bold mb-4">首页 Banner</h1><p class="mb-4">使用上下箭头调整轮播顺序；支持启停、定时发布和本站跳转。时间使用当前设备时区。建议图片比例 2.75:1，标题请勿写入未经开通的业务承诺。</p><form @submit.prevent="save"><article v-for="(b,i) in form.banners" :key="i" class="home-banner-editor"><header><b>Banner {{i+1}}</b><button type="button" :disabled="i===0" @click="move(i,-1)">↑</button><button type="button" :disabled="i===form.banners.length-1" @click="move(i,1)">↓</button><button type="button" @click="form.banners.splice(i,1)">移除</button><label><input type="checkbox" v-model="b.enabled"> 已启用</label></header><label>标题<input required maxlength="60" v-model.trim="b.title"></label><label>说明<input maxlength="120" v-model.trim="b.subtitle"></label><label>Banner 图片（可上传，或填写本站路径）<input v-model.trim="b.image" placeholder="/images/banner.jpg"><input type="file" accept="image/png,image/jpeg" @change="upload($event,b)"></label><label>本站跳转路径（留空显示暂未开通）<input v-model.trim="b.link" placeholder="/markets"></label><label>配色<themed-select v-model="b.tone"><option value="gold">浅金</option><option value="mint">薄荷绿</option><option value="blue">浅蓝</option></themed-select></label><label>开始时间<input type="datetime-local" v-model="b.start"></label><label>结束时间<input type="datetime-local" v-model="b.end"></label><div class="home-banner-preview" :class="b.tone"><img v-if="b.image" :src="b.image" alt="Banner 预览"><div><b>{{b.title}}</b><p>{{b.subtitle}}</p></div></div></article><button type="button" :disabled="form.banners.length>=20" @click="add">＋ 添加 Banner</button><label class="block my-4">修改原因<input class="block w-full" required minlength="5" maxlength="500" v-model.trim="form.reason"></label><p v-for="(error,k) in errors" :key="k" role="alert" class="text-red-600">{{error}}</p><button type="submit" :disabled="form.processing" class="px-4 py-2 bg-yellow-400 rounded">保存并发布</button><p role="alert">{{ uploadError }}</p><p v-if="saved" role="status">已保存</p></form><details class="mt-6"><summary>发布记录</summary><article v-for="h in history" :key="h.id" class="my-4">{{h.created_at}} · #{{h.actor_id}} · {{h.reason}}</article></details></app-layout></template>
<script>
import AppLayout from '@/Layouts/AdminLayout';
export default {components:{AppLayout},props:{banners:Array,history:Array,errors:Object},data(){return {uploadError:'',saved:false,form:this.$inertia.form({banners:this.banners.map(b=>({...b,start:this.local(b.start),end:this.local(b.end)})),reason:''})}},methods:{async upload(e,b){const file=e.target.files[0];if(!file)return;this.uploadError='';try{const f=new FormData();f.append('file',file);const {data}=await axios.post(this.route('file-upload'),f);b.image=new URL(data.path,location.origin).pathname}catch(err){this.uploadError=Object.values(err.response?.data?.errors||{}).flat().join(' ')||'图片上传失败'}},local(v){if(!v)return '';const d=new Date(v);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)},add(){this.form.banners.push({title:'',subtitle:'',image:'',link:'',tone:'gold',enabled:false,start:'',end:''})},move(i,d){this.form.banners.splice(i+d,0,this.form.banners.splice(i,1)[0])},save(){this.saved=false;this.form.transform(d=>({...d,banners:d.banners.map(b=>({...b,start:b.start?new Date(b.start).toISOString():null,end:b.end?new Date(b.end).toISOString():null}))})).put(this.route('admin.home-banners.update'),{preserveScroll:true,onSuccess:()=>{this.saved=true;this.form.reason=''}})}}};
</script><style scoped>.home-banner-editor{padding:20px;background:white;border:1px solid #ddd;border-radius:12px;margin:20px 0;display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}.home-banner-editor header{grid-column:1/-1;display:flex;gap:20px;align-items:center}.home-banner-editor label{display:block}.home-banner-editor input:not([type=checkbox]),.home-banner-editor select{display:block;width:100%;border:1px solid #ddd;border-radius:6px;padding:10px}.home-banner-editor button{padding:8px}.home-banner-preview{position:relative;border-radius:16px;min-height:130px;overflow:hidden;background:#fff4ce;color:#1a1a1a;padding:25px}.home-banner-preview.mint{background:#d9f5e9}.home-banner-preview.blue{background:#e2edff}.home-banner-preview img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.home-banner-preview div{position:relative}.home-banner-preview b{font-size:19px}.home-banner-preview p{margin-top:8px}</style>
